def tropical_witness_search(universe, cost):
    for x in universe:
        if cost(x) == 0:
            return x
    return None

def moser_tardos(n_vars, events, deps, max_iter=10000):
    assignment = [random.choice([True, False]) for _ in range(n_vars)]
    for _ in range(max_iter):
        violated = next((i for i, e in enumerate(events) if e(assignment)), None)
        if violated is None:
            return assignment
        for var in deps[violated]:
            assignment[var] = random.choice([True, False])
    return None

def erdos_ramsey_bound(k):
    edges = k * (k-1) // 2
    threshold = 2 ** edges
    best_n = 1
    for n in range(1, 100000):
        if 2 * math.comb(n, k) < threshold:
            best_n = n
        else:
            break
    return best_n
